export const validOnetAnswer=v=>Number.isInteger(v)&&v>=1&&v<=5;
export function cleanOnetInterest(raw){const out={instrument:onetInstrument.id,version:onetInstrument.version,answers:{}};if(!raw||raw.instrument!==onetInstrument.id||raw.version!==onetInstrument.version)return out;for(const q of onetQuestions)if(validOnetAnswer(raw.answers?.[q.id]))out.answers[q.id]=raw.answers[q.id];return out;}
export function scoreOnetInterest(s){const data=cleanOnetInterest(s.profileJourney?.officialInterest),answers=data.answers,answered=onetQuestions.filter(q=>validOnetAnswer(answers[q.id])).length,complete=answered===60;const groups=Object.fromEntries(riasecOrder.map(theme=>{const qs=onetQuestions.filter(q=>q.theme===theme),rated=qs.filter(q=>validOnetAnswer(answers[q.id]));return [theme,{theme,count:rated.length,raw:rated.length===10?rated.reduce((n,q)=>n+answers[q.id]-1,0):null,mean:rated.length?rated.reduce((n,q)=>n+answers[q.id],0)/rated.length:null,likes:rated.filter(q=>answers[q.id]>=4).map(q=>q.text)}];}));const raw=riasecOrder.map(t=>groups[t].raw),flat=complete&&Math.max(...raw)===Math.min(...raw),nearFlat=complete&&!flat&&(Math.max(...raw)-Math.min(...raw)<=2||60-Math.max(...[1,2,3,4,5].map(v=>Object.values(answers).filter(x=>x===v).length))<3);const max=complete?Math.max(...raw):null,positive=complete&&!flat?riasecOrder.filter(t=>groups[t].raw===max):[];return {instrument:onetInstrument.id,version:onetInstrument.version,groups,raw,answered,complete,enough:complete,flat,nearFlat,positive,kind:!answered?'empty':!complete?'partial':flat?'broad':'differentiated',unknown:60-answered,allDislike:complete&&raw.every(v=>v===0)};}
export function profileCorrelation(a,b){if(a.length!==6||b.length!==6||[...a,...b].some(v=>!Number.isFinite(v)))return null;const am=a.reduce((n,v)=>n+v,0)/6,bm=b.reduce((n,v)=>n+v,0)/6;let n=0,aa=0,bb=0;for(let i=0;i<6;i++){const x=a[i]-am,y=b[i]-bm;n+=x*y;aa+=x*x;bb+=y*y;}return aa>1e-12&&bb>1e-12?Math.max(-1,Math.min(1,n/Math.sqrt(aa*bb))):null;}
export function interestFit(r){return r===null?{tier:0,key:'unavailable',label:'Interest comparison unavailable'}:r>=.729?{tier:3,key:'very-strong',label:'Very strong interest alignment'}:r>=.608?{tier:2,key:'strong',label:'Strong interest alignment'}:r>=0?{tier:1,key:'overlap',label:'Some interest overlap'}:{tier:0,key:'different',label:'Different interest pattern'};}
